                const fbWisp = (() => { try { return ls.getItem('gust:fallback:wisp') || DEFAULT_FALLBACK_WISP; } catch { return DEFAULT_FALLBACK_WISP; } })();
                const candidates = poolOn ? rankPoolCandidates(host, WISP).slice(0, 3) : [];
